<?php
require_once __DIR__ . '/approval_workflow.php';
$apps = $pdo->query("SELECT ApplicationID FROM application WHERE Status NOT IN ('Draft','Withdrawn','Rejected','Disqualified')")->fetchAll(PDO::FETCH_COLUMN);
foreach ($apps as $applicationId) initializeApplicationWorkflow($pdo, (int) $applicationId);
$sql = "SELECT p.*, a.Status AS ApplicationStatus, a.TotalScore, a.ScholarshipID, s.Name AS ScholarshipName, s.CreatedBy, u.FirstName, u.LastName, u.StudentID_Num FROM application_workflow_progress p JOIN application a ON a.ApplicationID=p.ApplicationID JOIN scholarship s ON s.ScholarshipID=a.ScholarshipID JOIN users u ON u.UserID=a.UserID WHERE p.Status='In Progress' AND a.Status NOT IN ('Draft','Withdrawn','Rejected','Disqualified','Waitlisted','Waitlist Offered','Slot Vacated')";
$params = [];
if ($_SESSION['role'] !== 'Super_Admin') { $sql .= ' AND p.AssignedRole=?'; $params[] = $_SESSION['role']; }
if ($_SESSION['role'] === 'External_Admin') { $sql .= ' AND s.CreatedBy=?'; $params[] = $_SESSION['user_id']; }
$sql .= ' ORDER BY p.StartedAt, a.DateSubmitted';
$stmt=$pdo->prepare($sql);$stmt->execute($params);$workflowTasks=$stmt->fetchAll(PDO::FETCH_ASSOC);
?>
